export type Handler = (request: { path: string }, reply: { send(body: unknown): void }) => void;

export interface Hub {
  get(path: string, handler: Handler): this;
  /** Runs `plugin` with a hub whose routes are served under `options.prefix`. */
  register(plugin: (hub: Hub) => void | Promise<void>, options?: { prefix?: string }): this;
}

declare function hub(): Hub;
export default hub;
